def to_num(s, base):
    x = 0
    for i in range(len(s)):
        x += ord(s[-1-i]) * pow(base, i)
    return x

def get_nums(s, n):
    block_size = n
    sections = [s[i:i+block_size] for i in range(0, len(s), block_size)]
    if len(sections[-1]) < block_size:
        sections[-1] += b'\x00' * (block_size - len(sections[-1]))
    return [to_num(x, 256) for x in sections]

def get_vals(x, n):
    vals = []
    mask = (1 << n) - 1
    for i in range(8):
        vals.append(x & mask)
        x >>= n
    vals.reverse()
    return vals

def get_chrs(val_list, n):
